class Solution {
public:
    int minimumTime(std::vector<std::vector<int>>& grid) {
        if (grid[0][1] > 1 && grid[1][0] > 1) return -1;
        int m = grid.size(), n = grid[0].size();
        std::vector<std::vector<int>> dist(m, std::vector<int>(n, INT_MAX));
        dist[0][0] = 0;
        using State = std::tuple<int, int, int>;
        std::priority_queue<State, std::vector<State>, std::greater<State>> pq;
        pq.push({0, 0, 0});
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!pq.empty()) {
            auto [t, r, c] = pq.top();
            pq.pop();
            if (r == m - 1 && c == n - 1) return t;
            if (t > dist[r][c]) continue;
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    int nt = 0;
                    if (t + 1 >= grid[nr][nc]) {
                        nt = t + 1;
                    } else {
                        int diff = grid[nr][nc] - t;
                        nt = (diff % 2 == 1) ? grid[nr][nc] : grid[nr][nc] + 1;
                    }
                    if (nt < dist[nr][nc]) {
                        dist[nr][nc] = nt;
                        pq.push({nt, nr, nc});
                    }
                }
            }
        }
        return -1;
    }
};

class Solution {
    public int minimumTime(int[][] grid) {
        if (grid[0][1] > 1 && grid[1][0] > 1) return -1;
        int m = grid.length, n = grid[0].length;
        int[][] dist = new int[m][n];
        for (int[] row : dist) java.util.Arrays.fill(row, Integer.MAX_VALUE);
        dist[0][0] = 0;
        java.util.PriorityQueue<int[]> pq = new java.util.PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        pq.offer(new int[]{0, 0, 0});
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int t = curr[0], r = curr[1], c = curr[2];
            if (r == m - 1 && c == n - 1) return t;
            if (t > dist[r][c]) continue;
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    int nt;
                    if (t + 1 >= grid[nr][nc]) {
                        nt = t + 1;
                    } else {
                        int diff = grid[nr][nc] - t;
                        nt = (diff % 2 == 1) ? grid[nr][nc] : grid[nr][nc] + 1;
                    }
                    if (nt < dist[nr][nc]) {
                        dist[nr][nc] = nt;
                        pq.offer(new int[]{nt, nr, nc});
                    }
                }
            }
        }
        return -1;
    }
}

var minimumTime = function(grid) {
    if (grid[0][1] > 1 && grid[1][0] > 1) return -1;
    const m = grid.length, n = grid[0].length;
    const dist = Array.from({ length: m }, () => new Int32Array(n).fill(1e9));
    dist[0][0] = 0;
    // Simple min-heap simulation with binary heap or flat array for grid sizes
    const heap = [[0, 0, 0]];
    const push = (item) => {
        heap.push(item);
        let idx = heap.length - 1;
        while (idx > 0) {
            let p = (idx - 1) >> 1;
            if (heap[p][0] > heap[idx][0]) {
                let temp = heap[p];
                heap[p] = heap[idx];
                heap[idx] = temp;
                idx = p;
            } else break;
        }
    };
    const pop = () => {
        const top = heap[0];
        const end = heap.pop();
        if (heap.length > 0) {
            heap[0] = end;
            let idx = 0;
            const len = heap.length;
            while ((idx << 1) + 1 < len) {
                let left = (idx << 1) + 1;
                let right = left + 1;
                let best = (right < len && heap[right][0] < heap[left][0]) ? right : left;
                if (heap[best][0] < heap[idx][0]) {
                    let temp = heap[best];
                    heap[best] = heap[idx];
                    heap[idx] = temp;
                    idx = best;
                } else break;
            }
        }
        return top;
    };
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    while (heap.length > 0) {
        const [t, r, c] = pop();
        if (r === m - 1 && c === n - 1) return t;
        if (t > dist[r][c]) continue;
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                let nt;
                if (t + 1 >= grid[nr][nc]) {
                    nt = t + 1;
                } else {
                    let diff = grid[nr][nc] - t;
                    nt = (diff % 2 === 1) ? grid[nr][nc] : grid[nr][nc] + 1;
                }
                if (nt < dist[nr][nc]) {
                    dist[nr][nc] = nt;
                    push([nt, nr, nc]);
                }
            }
        }
    }
    return -1;
};
